"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[9708],{9668(e,a,i){i.r(a),i.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>r,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"cursos/diseno-apis/modulos/fundamentos-api-rest/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfDe d\xf3nde proviene exactamente la distinci\xf3n entre \\"REST\\" y \\"RESTful\\" y qui\xe9n fue el primero en articularla formalmente? \xbfQu\xe9 opina Fielding de esta distinci\xf3n?","source":"@site/docs/cursos/diseno-apis/modulos/01-fundamentos-api-rest/cuestionario.md","sourceDirName":"cursos/diseno-apis/modulos/01-fundamentos-api-rest","slug":"/cursos/diseno-apis/modulos/fundamentos-api-rest/cuestionario","permalink":"/sasf-temarios/cursos/diseno-apis/modulos/fundamentos-api-rest/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/diseno-apis/modulos/fundamentos-api-rest/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/diseno-apis/modulos/fundamentos-api-rest/ejercicio"}}');var o=i(74848),s=i(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},t=void 0,c={},l=[{value:"2. [Investigar] \xbfDe d\xf3nde proviene exactamente la distinci\xf3n entre &quot;REST&quot; y &quot;RESTful&quot; y qui\xe9n fue el primero en articularla formalmente? \xbfQu\xe9 opina Fielding de esta distinci\xf3n?",id:"2-investigar-de-d\xf3nde-proviene-exactamente-la-distinci\xf3n-entre-rest-y-restful-y-qui\xe9n-fue-el-primero-en-articularla-formalmente-qu\xe9-opina-fielding-de-esta-distinci\xf3n",level:3},{value:"3. [Investigar] \xbfCu\xe1l fue el rol de Roy Fielding en la especificaci\xf3n HTTP/1.1 original y en su revisi\xf3n? \xbfC\xf3mo influy\xf3 la arquitectura REST en el dise\xf1o del protocolo HTTP?",id:"3-investigar-cu\xe1l-fue-el-rol-de-roy-fielding-en-la-especificaci\xf3n-http11-original-y-en-su-revisi\xf3n-c\xf3mo-influy\xf3-la-arquitectura-rest-en-el-dise\xf1o-del-protocolo-http",level:3},{value:"4. [Investigar] \xbfQu\xe9 otras restricciones arquitect\xf3nicas explor\xf3 Fielding en su tesis doctoral que no llegaron a formar parte de REST? \xbfPor qu\xe9 fueron descartadas?",id:"4-investigar-qu\xe9-otras-restricciones-arquitect\xf3nicas-explor\xf3-fielding-en-su-tesis-doctoral-que-no-llegaron-a-formar-parte-de-rest-por-qu\xe9-fueron-descartadas",level:3},{value:"5. [Conectar] La clase ense\xf1a que REST es stateless por escalabilidad. \xbfC\xf3mo interact\xfaa el principio de statelessness con legislaciones de privacidad como GDPR que requieren &quot;derecho al olvido&quot;? \xbfD\xf3nde se almacena realmente el estado en una API RESTful?",id:"5-conectar-la-clase-ense\xf1a-que-rest-es-stateless-por-escalabilidad-c\xf3mo-interact\xfaa-el-principio-de-statelessness-con-legislaciones-de-privacidad-como-gdpr-que-requieren-derecho-al-olvido-d\xf3nde-se-almacena-realmente-el-estado-en-una-api-restful",level:3},{value:"6. [Conectar] \xbfC\xf3mo se relaciona la restricci\xf3n de &quot;Cacheability&quot; de REST con el funcionamiento de CDNs modernos como CloudFront, Akamai y Cloudflare? \xbfQu\xe9 headers de la clase son esenciales para esta integraci\xf3n?",id:"6-conectar-c\xf3mo-se-relaciona-la-restricci\xf3n-de-cacheability-de-rest-con-el-funcionamiento-de-cdns-modernos-como-cloudfront-akamai-y-cloudflare-qu\xe9-headers-de-la-clase-son-esenciales-para-esta-integraci\xf3n",level:3},{value:"7. [Conectar] \xbfC\xf3mo se mapea la restricci\xf3n &quot;Layered System&quot; de REST a las arquitecturas modernas de API Gateway con microservicios? \xbfEs Kong, Apigee o Envoy una implementaci\xf3n directa de esta restricci\xf3n?",id:"7-conectar-c\xf3mo-se-mapea-la-restricci\xf3n-layered-system-de-rest-a-las-arquitecturas-modernas-de-api-gateway-con-microservicios-es-kong-apigee-o-envoy-una-implementaci\xf3n-directa-de-esta-restricci\xf3n",level:3},{value:"8. [Cuestionar] \xbfPor qu\xe9 la mayor\xeda de las APIs consideradas exitosas (Stripe, Twilio, GitHub) operan en Nivel 2 del modelo de Richardson y no en Nivel 3 (HATEOAS)? \xbfEs el modelo de Richardson pr\xe1ctico o acad\xe9mico?",id:"8-cuestionar-por-qu\xe9-la-mayor\xeda-de-las-apis-consideradas-exitosas-stripe-twilio-github-operan-en-nivel-2-del-modelo-de-richardson-y-no-en-nivel-3-hateoas-es-el-modelo-de-richardson-pr\xe1ctico-o-acad\xe9mico",level:3},{value:"9. [Cuestionar] &quot;Code on Demand&quot; es la \xfanica restricci\xf3n opcional de REST. \xbfPor qu\xe9 Fielding la hizo opcional en lugar de obligatoria? \xbfQu\xe9 riesgos de seguridad introduce y por qu\xe9 fracas\xf3 en APIs modernas?",id:"9-cuestionar-code-on-demand-es-la-\xfanica-restricci\xf3n-opcional-de-rest-por-qu\xe9-fielding-la-hizo-opcional-en-lugar-de-obligatoria-qu\xe9-riesgos-de-seguridad-introduce-y-por-qu\xe9-fracas\xf3-en-apis-modernas",level:3},{value:"10. [Cuestionar] A pesar de que REST se cre\xf3 en 2000 y SOAP se considera legacy, \xbfpor qu\xe9 sectores como banca, gobierno y healthcare siguen usando SOAP en 2026? \xbfEs siempre REST t\xe9cnicamente superior?",id:"10-cuestionar-a-pesar-de-que-rest-se-cre\xf3-en-2000-y-soap-se-considera-legacy-por-qu\xe9-sectores-como-banca-gobierno-y-healthcare-siguen-usando-soap-en-2026-es-siempre-rest-t\xe9cnicamente-superior",level:3}];function d(e){const a={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(a.h3,{id:"2-investigar-de-d\xf3nde-proviene-exactamente-la-distinci\xf3n-entre-rest-y-restful-y-qui\xe9n-fue-el-primero-en-articularla-formalmente-qu\xe9-opina-fielding-de-esta-distinci\xf3n",children:'2. [Investigar] \xbfDe d\xf3nde proviene exactamente la distinci\xf3n entre "REST" y "RESTful" y qui\xe9n fue el primero en articularla formalmente? \xbfQu\xe9 opina Fielding de esta distinci\xf3n?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': La distinci\xf3n "REST" (estilo arquitect\xf3nico puro con las 6 constraints) vs "RESTful" (API que sigue la mayor\xeda de las constraints pero quiz\xe1s no HATEOAS) fue popularizada por Leonard Richardson en su charla "Justice Will Take Us Millions Of Intricate Moves" (QCon 2008), donde present\xf3 el modelo de madurez. Sin embargo, Fielding ha sido expl\xedcito: "There is no such thing as a RESTful API. Something is either REST or it isn\'t." Para Fielding no hay grados; la distinci\xf3n es una concesi\xf3n pragm\xe1tica de la industria que \xe9l rechaza.']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': Richardson, al presentar su modelo en QCon SF 2008 (y posteriormente codificado por Martin Fowler en su blog "Richardson Maturity Model", 2010), cre\xf3 los niveles 0-3 justamente porque la industria ya llamaba "REST" a cosas que no lo eran. La evidencia est\xe1 en que el propio Fowler escribe: "I\'ve spoken to Roy Fielding and he would say that to be truly RESTful you need level 3." La distinci\xf3n REST vs RESTful es, por tanto, un artefacto de la industria para resolver la tensi\xf3n entre pureza arquitect\xf3nica y pragmatismo \u2014 Fielding nunca la acept\xf3, pero el mercado la adopt\xf3.']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"3-investigar-cu\xe1l-fue-el-rol-de-roy-fielding-en-la-especificaci\xf3n-http11-original-y-en-su-revisi\xf3n-c\xf3mo-influy\xf3-la-arquitectura-rest-en-el-dise\xf1o-del-protocolo-http",children:"3. [Investigar] \xbfCu\xe1l fue el rol de Roy Fielding en la especificaci\xf3n HTTP/1.1 original y en su revisi\xf3n? \xbfC\xf3mo influy\xf3 la arquitectura REST en el dise\xf1o del protocolo HTTP?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Fielding fue co-autor principal de RFC 2616 (HTTP/1.1, 1999) y uno de los editores principales de las RFCs 7230-7235 que revisaron y reemplazaron RFC 2616 en 2014. Su tesis doctoral analiz\xf3 la arquitectura de la Web existente y destil\xf3 REST como el estilo arquitect\xf3nico que explica su \xe9xito. El dise\xf1o de HTTP refleja REST: m\xe9todos bien definidos (GET seguro e idempotente, PUT idempotente), headers de cach\xe9 (Cache-Control, ETag), negociaci\xf3n de contenido (Accept, Content-Type), y c\xf3digos de estado sem\xe1nticos \u2014 todas construcciones que provienen de aplicar las restricciones REST al protocolo."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': La tesis de Fielding (UC Irvine, 2000) se titula "Architectural Styles and the Design of Network-based Software Architectures" y dedica el cap\xedtulo 6 a "Experience and Evaluation" donde explica c\xf3mo REST se deriv\xf3 del dise\xf1o de HTTP. No es casualidad: Fielding fue el principal arquitecto de HTTP/1.1 en el IETF. La revisi\xf3n RFC 7230-7235 (2014) que \xe9l co-edit\xf3 clarific\xf3 exactamente los conceptos que la industria usaba mal (idempotencia de DELETE, respuesta 201 con Location, sem\xe1ntica de PATCH que qued\xf3 en RFC 5789). Esta conexi\xf3n entre su rol en el IETF y su tesis demuestra que REST no es teor\xeda abstracta sino ingenier\xeda de protocolos aplicada.']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"4-investigar-qu\xe9-otras-restricciones-arquitect\xf3nicas-explor\xf3-fielding-en-su-tesis-doctoral-que-no-llegaron-a-formar-parte-de-rest-por-qu\xe9-fueron-descartadas",children:"4. [Investigar] \xbfQu\xe9 otras restricciones arquitect\xf3nicas explor\xf3 Fielding en su tesis doctoral que no llegaron a formar parte de REST? \xbfPor qu\xe9 fueron descartadas?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": La tesis de Fielding analiza estilos arquitect\xf3nicos como Pipe and Filter, Client-Server, Layered, Replicated Repository, Cache, Mobile Code, Event-based Integration, y Distributed Objects antes de derivar REST. REST es la combinaci\xf3n de restricciones que Fielding dedujo al analizar por qu\xe9 la Web funcionaba. Las restricciones que explor\xf3 pero no incluy\xf3 como necesarias incluyen: procesamiento peer-to-peer sim\xe9trico (porque la Web es inherentemente cliente-servidor asim\xe9trico), estado compartido entre capas (rechazado por la restricci\xf3n stateless), y objetos distribuidos al estilo CORBA/DCOM (rechazados por acoplar interfaz con implementaci\xf3n, violando la uniform interface)."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': El proceso de Fielding fue inductivo, no deductivo: no invent\xf3 REST y luego dise\xf1\xf3 HTTP, sino que observ\xf3 HTTP/1.1 y la Web temprana y destil\xf3 qu\xe9 restricciones explicaban su escalabilidad y flexibilidad. En el Cap\xedtulo 5 de su tesis, deriva REST como un "architectural style for distributed hypermedia systems" evaluando sistem\xe1ticamente las propiedades inducidas por cada restricci\xf3n: simplicidad, visibilidad, escalabilidad, modificabilidad, portabilidad y confiabilidad. El estilo Mobile Code fue incluido como opcional (Code on Demand) porque Fielding reconoci\xf3 que JavaScript y applets ya exist\xedan pero no eran esenciales para la arquitectura. Los objetos distribuidos fueron rechazados expl\xedcitamente por requerir binding est\xe1tico entre interfaz e implementaci\xf3n.']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"5-conectar-la-clase-ense\xf1a-que-rest-es-stateless-por-escalabilidad-c\xf3mo-interact\xfaa-el-principio-de-statelessness-con-legislaciones-de-privacidad-como-gdpr-que-requieren-derecho-al-olvido-d\xf3nde-se-almacena-realmente-el-estado-en-una-api-restful",children:'5. [Conectar] La clase ense\xf1a que REST es stateless por escalabilidad. \xbfC\xf3mo interact\xfaa el principio de statelessness con legislaciones de privacidad como GDPR que requieren "derecho al olvido"? \xbfD\xf3nde se almacena realmente el estado en una API RESTful?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": El estado no desaparece \u2014 se traslada al cliente o se persiste como recurso. En una API RESTful stateless, los datos del usuario no est\xe1n en sesiones ef\xedmeras del servidor sino en la base de datos como recursos. Para GDPR, esto es una ventaja: los datos son recursos con URLs, lo que facilita implementar el derecho al olvido (DELETE del recurso ",(0,o.jsx)(a.code,{children:"User"}),' y sus recursos relacionados). Pero tambi\xe9n crea responsabilidad: si el estado est\xe1 en el cliente (ej. un JWT con claims), el servidor no lo "recuerda" \u2014 pero el token puede contener PII (Personal Identifiable Information) que el cliente almacena, y bajo GDPR el cliente (frontend) es un procesador de datos.']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': La conexi\xf3n REST-GDPR no es obvia. GDPR Art\xedculo 17 establece el derecho de supresi\xf3n ("right to be forgotten"). En arquitecturas stateful, el estado en sesi\xf3n del servidor es dif\xedcil de rastrear y eliminar completamente. En REST, cada dato tiene una URL, y cada recurso puede ser eliminado con DELETE. Sin embargo, el IETF Naveed et al. (2015) en "Privacy Considerations for Internet Protocols" (RFC 6973) advierte que los tokens JWT transportados en headers pueden ser logs en proxies y load balancers que no se eliminan con DELETE. La soluci\xf3n: tokens con claims m\xednimos (solo ',(0,o.jsx)(a.code,{children:"sub"}),"), y datos sensibles siempre del lado del servidor."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"6-conectar-c\xf3mo-se-relaciona-la-restricci\xf3n-de-cacheability-de-rest-con-el-funcionamiento-de-cdns-modernos-como-cloudfront-akamai-y-cloudflare-qu\xe9-headers-de-la-clase-son-esenciales-para-esta-integraci\xf3n",children:'6. [Conectar] \xbfC\xf3mo se relaciona la restricci\xf3n de "Cacheability" de REST con el funcionamiento de CDNs modernos como CloudFront, Akamai y Cloudflare? \xbfQu\xe9 headers de la clase son esenciales para esta integraci\xf3n?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': La cacheability de REST es exactamente lo que permite a las CDNs funcionar como "intermediarios transparentes" en el Layered System de REST. Una CDN es esencialmente un reverse proxy cache que implementa la restricci\xf3n de cache. Los headers clave son: ',(0,o.jsx)(a.code,{children:"Cache-Control: public, max-age=3600"})," (le dice a la CDN que puede cachear la respuesta y por cu\xe1nto tiempo), ",(0,o.jsx)(a.code,{children:"ETag"})," + ",(0,o.jsx)(a.code,{children:"If-None-Match"}),' (permite revalidaci\xf3n condicional: la CDN pregunta al origen "\xbfcambi\xf3 esto?"), y ',(0,o.jsx)(a.code,{children:"Vary: Accept, Authorization"})," (le dice a la CDN c\xf3mo particionar el cach\xe9). Sin estos headers configurados correctamente, la CDN no cachea o \u2014peor\u2014 cachea incorrectamente."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': La restricci\xf3n de cache (Fielding, tesis 2000, Secci\xf3n 5.1.4) establece que "los datos de respuesta deben ser impl\xedcita o expl\xedcitamente etiquetados como cacheables o no cacheables". CloudFront (AWS) y Akamai son implementaciones masivas de esta restricci\xf3n a escala de Internet. CloudFront respeta ',(0,o.jsx)(a.code,{children:"Cache-Control"}),", ",(0,o.jsx)(a.code,{children:"Expires"}),", y ",(0,o.jsx)(a.code,{children:"Vary"})," exactamente como Fielding lo defini\xf3. Los errores comunes en APIs REST que desperdician CDNs son: usar ",(0,o.jsx)(a.code,{children:"Cache-Control: no-store"})," globalmente (deshabilita la CDN completamente), olvidar ",(0,o.jsx)(a.code,{children:"Vary"})," cuando la respuesta var\xeda por header (puede cachear el resultado del usuario A y serv\xedrselo al usuario B), o no configurar ",(0,o.jsx)(a.code,{children:"ETag"})," para requests condicionales (cada request llega al origen innecesariamente). La especificaci\xf3n de HTTP Caching est\xe1 en RFC 7234."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"7-conectar-c\xf3mo-se-mapea-la-restricci\xf3n-layered-system-de-rest-a-las-arquitecturas-modernas-de-api-gateway-con-microservicios-es-kong-apigee-o-envoy-una-implementaci\xf3n-directa-de-esta-restricci\xf3n",children:'7. [Conectar] \xbfC\xf3mo se mapea la restricci\xf3n "Layered System" de REST a las arquitecturas modernas de API Gateway con microservicios? \xbfEs Kong, Apigee o Envoy una implementaci\xf3n directa de esta restricci\xf3n?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': La restricci\xf3n "Layered System" establece que un cliente no puede distinguir si est\xe1 conectado directamente al servidor final o a un intermediario. Un API Gateway moderno (Kong, Apigee, Envoy, AWS API Gateway) es exactamente un intermediario que implementa esta restricci\xf3n: el cliente cree que habla con "la API", pero el gateway enruta a m\xfaltiples microservicios internos, aplica rate limiting, autenticaci\xf3n, logging y transformaci\xf3n. El cliente no sabe ni necesita saber que detr\xe1s del gateway hay 20 servicios diferentes.']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por Qu\xe9"}),': Fielding describe la restricci\xf3n "Layered System" como aquella donde "cada componente no puede ver m\xe1s all\xe1 de la capa inmediata con la que interact\xfaa" (tesis, Secci\xf3n 5.1.6). Esto permite balanceadores de carga (HAProxy, Nginx), firewalls (WAF), y caches compartidos (Varnish) que mejoran escalabilidad y seguridad sin que el cliente modifique su c\xf3digo. Kong y Apigee a\xf1aden capacidades que Fielding anticip\xf3: transformaci\xf3n de protocolos, composici\xf3n de respuestas, y seguridad perimetral. La diferencia clave: un API Gateway que expone endpoints diferentes internamente de los que el cliente ve implementa Layered System; uno que obliga al cliente a saber cu\xe1l microservicio llamar directamente lo viola. RFC 7230 (Secci\xf3n 2.2) formaliza los intermediarios HTTP como "proxies, gateways y t\xfaneles."']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"8-cuestionar-por-qu\xe9-la-mayor\xeda-de-las-apis-consideradas-exitosas-stripe-twilio-github-operan-en-nivel-2-del-modelo-de-richardson-y-no-en-nivel-3-hateoas-es-el-modelo-de-richardson-pr\xe1ctico-o-acad\xe9mico",children:"8. [Cuestionar] \xbfPor qu\xe9 la mayor\xeda de las APIs consideradas exitosas (Stripe, Twilio, GitHub) operan en Nivel 2 del modelo de Richardson y no en Nivel 3 (HATEOAS)? \xbfEs el modelo de Richardson pr\xe1ctico o acad\xe9mico?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': Stripe, Twilio y GitHub operan en Nivel 2 porque HATEOAS (Nivel 3) agrega complejidad sin suficiente retorno de inversi\xf3n percibido para sus casos de uso. Estas empresas priorizan: SDKs en m\xfaltiples lenguajes que hardcodean las URLs, documentaci\xf3n OpenAPI de alta calidad, y versionado expl\xedcito \u2014 exactamente lo opuesto a la "autodescubribilidad" de HATEOAS. El argumento pragm\xe1tico es que cuando control\xe1s tanto el servidor como los SDKs oficiales, la descoordinaci\xf3n servidor-cliente que HATEOAS resuelve no es un problema real.']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': Stripe tiene m\xe1s de 20 SDKs oficiales; si cambiaran las URLs, actualizar\xedan los SDKs. Para clientes que no usan SDKs, Stripe provee documentaci\xf3n interactiva y versionado basado en fecha. GitHub usa una estrategia similar con su API v3/v4. Ninguna de estas empresas reporta problemas de evoluci\xf3n de APIs que HATEOAS hubiera resuelto mejor. El debate es: \xbfRichardson cre\xf3 un modelo prescriptivo (lo que deber\xeda ser REST) o descriptivo (lo que la industria hace)? Martin Fowler en su art\xedculo original (2010) lo presenta como "una forma de pensar en el uso de REST", no como un checklist. Sin embargo, Fielding ha dicho (en comentarios online) que el modelo es \xfatil pero que la gente confunde "alcanzar Nivel 2" con "ser REST".']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"9-cuestionar-code-on-demand-es-la-\xfanica-restricci\xf3n-opcional-de-rest-por-qu\xe9-fielding-la-hizo-opcional-en-lugar-de-obligatoria-qu\xe9-riesgos-de-seguridad-introduce-y-por-qu\xe9-fracas\xf3-en-apis-modernas",children:'9. [Cuestionar] "Code on Demand" es la \xfanica restricci\xf3n opcional de REST. \xbfPor qu\xe9 Fielding la hizo opcional en lugar de obligatoria? \xbfQu\xe9 riesgos de seguridad introduce y por qu\xe9 fracas\xf3 en APIs modernas?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Fielding la hizo opcional porque observ\xf3 que la Web (HTML + JavaScript) ya usaba code-on-demand y funcionaba, pero no era esencial para la arquitectura: se puede tener una Web completamente funcional con HTML est\xe1tico. Los riesgos de seguridad incluyen: ejecuci\xf3n de c\xf3digo no confiable del servidor en el cliente (XSS), violaci\xf3n de sandbox, y dependencia de un runtime espec\xedfico (Java applets, Flash). Fracas\xf3 en APIs modernas porque: (1) los clientes de API son c\xf3digo programado, no navegadores que ejecutan scripts din\xe1micamente; (2) los riesgos de seguridad son inaceptables en entornos server-to-server; (3) el patr\xf3n se reemplaz\xf3 por SDKs pre-compilados distribuidos por package managers."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': La tesis de Fielding (Secci\xf3n 5.1.7) dice: "REST allows client functionality to be extended by downloading and executing code in the form of applets or scripts. This simplifies clients by reducing the number of features required to be pre-implemented." La palabra clave es "allows" \u2014 no "requires". En la Web de 2000, JavaScript y Java applets eran el code-on-demand natural. En APIs de 2024, el code-on-demand m\xe1s cercano es OpenAPI \u2192 generaci\xf3n de c\xf3digo (pero esto ocurre en tiempo de dise\xf1o, no runtime) o los webhooks que env\xedan payloads que el cliente procesa con l\xf3gica propia. La realidad es que esta restricci\xf3n qued\xf3 como una curiosidad hist\xf3rica; ning\xfan dise\xf1o moderno de API RESTful la implementa.']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"10-cuestionar-a-pesar-de-que-rest-se-cre\xf3-en-2000-y-soap-se-considera-legacy-por-qu\xe9-sectores-como-banca-gobierno-y-healthcare-siguen-usando-soap-en-2026-es-siempre-rest-t\xe9cnicamente-superior",children:"10. [Cuestionar] A pesar de que REST se cre\xf3 en 2000 y SOAP se considera legacy, \xbfpor qu\xe9 sectores como banca, gobierno y healthcare siguen usando SOAP en 2026? \xbfEs siempre REST t\xe9cnicamente superior?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": SOAP sobrevive en sectores regulados porque ofrece: (1) Contrato estricto v\xeda WSDL que act\xfaa como especificaci\xf3n legalmente vinculante entre sistemas. (2) WS-Security, WS-ReliableMessaging, WS-AtomicTransaction \u2014 est\xe1ndares maduros que REST no tiene equivalentes nativos estandarizados para transacciones distribuidas y mensajer\xeda confiable. (3) Herramientas de generaci\xf3n de c\xf3digo enterprise (IBM WebSphere, Oracle WebLogic) embebidas en procesos de compliance. REST no es t\xe9cnicamente superior para transacciones financieras que requieren atomicidad distribuida, ni para intercambios B2B donde el contrato WSDL es parte del acuerdo legal entre empresas."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': SWIFT (banca internacional) usa ISO 20022 sobre SOAP. HL7 FHIR (healthcare) migr\xf3 a REST reci\xe9n en 2014 pero convive con SOAP porque hospitales legacy no pueden migrar. El gobierno de EE.UU. (FISMA, FedRAMP) exige ciertos controles que WS-Security provee nativamente. Stefan Tilkov (innoQ, autor de "REST und HTTP") argumenta que REST es superior en escenarios de Internet abierto (escalabilidad, caching, simplicidad) pero que SOAP fue dise\xf1ado para escenarios enterprise con requisitos de transaccionalidad, seguridad a nivel de mensaje y contratos formales que REST no intent\xf3 resolver. No es cuesti\xf3n de "REST es mejor" sino de "REST resuelve un problema distinto".']})]})}function u(e={}){const{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,o.jsx)(a,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,a,i){i.d(a,{R:()=>r,x:()=>t});var n=i(96540);const o={},s=n.createContext(o);function r(e){const a=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),n.createElement(s.Provider,{value:a},e.children)}}}]);